1	/**
2	 * stripe-webhook — Edge Function
3	 *
4	 * Handles incoming Stripe webhook events and keeps the profiles table
5	 * in sync with subscription state.
6	 *
7	 * Handled events:
8	 *   checkout.session.completed     → activate plan, set scan_limit, billing_cycle_end
9	 *   customer.subscription.updated  → sync plan changes (upgrade / downgrade)
10	 *   customer.subscription.deleted  → downgrade to free, clear billing data
11	 *   invoice.payment_failed         → log failure for observability
12	 *
13	 * Required env vars:
14	 *   STRIPE_SECRET_KEY
15	 *   STRIPE_WEBHOOK_SECRET          (from Stripe dashboard → webhook endpoint)
16	 *   SUPABASE_URL
17	 *   SUPABASE_SERVICE_ROLE_KEY
18	 *
19	 * Security: Stripe-Signature header is verified before any processing.
20	 * No auth cookie / JWT required — Stripe calls this endpoint directly.
21	 */
22	
23	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
24	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
25	import Stripe from "https://esm.sh/stripe@14?target=deno";
26	
27	// ── Plan config ───────────────────────────────────────────────────
28	
29	type PlanType = "free" | "pro" | "agency";
30	
31	const PLAN_LIMITS: Record<PlanType, number> = {
32	  free: 3,
33	  pro: 50,
34	  agency: 500,
35	};
36	
37	// Derive plan from Stripe price IDs at runtime
38	function getPlanFromPriceId(priceId: string): PlanType {
39	  const proMonthly = Deno.env.get("STRIPE_PRICE_PRO_MONTHLY");
40	  const proAnnual = Deno.env.get("STRIPE_PRICE_PRO_ANNUAL");
41	  const agencyMonthly = Deno.env.get("STRIPE_PRICE_AGENCY_MONTHLY");
42	  const agencyAnnual = Deno.env.get("STRIPE_PRICE_AGENCY_ANNUAL");
43	
44	  if (priceId === proMonthly || priceId === proAnnual) return "pro";
45	  if (priceId === agencyMonthly || priceId === agencyAnnual) return "agency";
46	
47	  // Unknown price ID — default safe
48	  console.warn(`Unknown price ID: ${priceId}. Defaulting to 'pro'.`);
49	  return "pro";
50	}
51	
52	// ── Serve ─────────────────────────────────────────────────────────
53	
54	serve(async (req: Request) => {
55	  // Webhook endpoint does NOT handle CORS OPTIONS — Stripe never sends preflight.
56	  // Only POST requests arrive here.
57	
58	  const signature = req.headers.get("stripe-signature");
59	  if (!signature) {
60	    return new Response(
61	      JSON.stringify({ error: "Missing Stripe-Signature header" }),
62	      { status: 400, headers: { "Content-Type": "application/json" } }
63	    );
64	  }
65	
66	  const webhookSecret = Deno.env.get("STRIPE_WEBHOOK_SECRET");
67	  if (!webhookSecret) {
68	    console.error("STRIPE_WEBHOOK_SECRET env var not set");
69	    return new Response(
70	      JSON.stringify({ error: "Webhook secret not configured" }),
71	      { status: 500, headers: { "Content-Type": "application/json" } }
72	    );
73	  }
74	
75	  const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
76	    apiVersion: "2024-06-20",
77	    httpClient: Stripe.createFetchHttpClient(),
78	  });
79	
80	  // ── Verify signature ─────────────────────────────────────────────
81	  const body = await req.text();
82	  let event: Stripe.Event;
83	
84	  try {
85	    event = await stripe.webhooks.constructEventAsync(body, signature, webhookSecret);
86	  } catch (err: unknown) {
87	    const message = err instanceof Error ? err.message : "Invalid signature";
88	    console.error("Webhook signature verification failed:", message);
89	    return new Response(
90	      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
91	      { status: 400, headers: { "Content-Type": "application/json" } }
92	    );
93	  }
94	
95	  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
96	  const supabase = createClient(
97	    Deno.env.get("SUPABASE_URL") ?? "",
98	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
99	  );
100	
101	  // ── Event routing ─────────────────────────────────────────────────
102	  try {
103	    switch (event.type) {
104	      // ── checkout.session.completed ───────────────────────────────
105	      case "checkout.session.completed": {
106	        const session = event.data.object as Stripe.Checkout.Session;
107	        const userId = session.metadata?.user_id;
108	        const plan = (session.metadata?.plan ?? "pro") as PlanType;
109	
110	        if (!userId) {
111	          console.error("checkout.session.completed: missing user_id in metadata");
112	          break;
113	        }
114	
115	        // Fetch the created subscription to get billing period end
116	        let billingCycleEnd: string | null = null;
117	        if (session.subscription) {
118	          const subscription = await stripe.subscriptions.retrieve(
119	            session.subscription as string
120	          );
121	          billingCycleEnd = new Date(
122	            subscription.current_period_end * 1000
123	          ).toISOString();
124	        }
125	
126	        const { error } = await supabase
127	          .from("profiles")
128	          .update({
129	            plan,
130	            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
131	            stripe_subscription_id: session.subscription ?? null,
132	            billing_cycle_end: billingCycleEnd,
133	            updated_at: new Date().toISOString(),
134	          })
135	          .eq("id", userId);
136	
137	        if (error) {
138	          console.error("checkout.session.completed profile update error:", error);
139	        } else {
140	          console.log(`Activated ${plan} plan for user ${userId}`);
141	        }
142	        break;
143	      }
144	
145	      // ── customer.subscription.updated ────────────────────────────
146	      case "customer.subscription.updated": {
147	        const subscription = event.data.object as Stripe.Subscription;
148	
149	        // Find user by stripe_customer_id
150	        const { data: profile, error: profileError } = await supabase
151	          .from("profiles")
152	          .select("id, plan")
153	          .eq("stripe_customer_id", subscription.customer as string)
154	          .single();
155	
156	        if (profileError || !profile) {
157	          console.error(
158	            "customer.subscription.updated: profile not found for customer",
159	            subscription.customer
160	          );
161	          break;
162	        }
163	
164	        // Derive new plan from the subscription's first price item
165	        const priceId = subscription.items.data[0]?.price?.id;
166	        const newPlan: PlanType = priceId
167	          ? getPlanFromPriceId(priceId)
168	          : profile.plan;
169	
170	        const billingCycleEnd = new Date(
171	          subscription.current_period_end * 1000
172	        ).toISOString();
173	
174	        // Map subscription status to plan — cancelled/past_due → keep current until period end
175	        const isActive =
176	          subscription.status === "active" ||
177	          subscription.status === "trialing";
178	
179	        const { error } = await supabase
180	          .from("profiles")
181	          .update({
182	            plan: isActive ? newPlan : profile.plan,
183	            scan_limit: isActive
184	              ? PLAN_LIMITS[newPlan] ?? PLAN_LIMITS.pro
185	              : PLAN_LIMITS[profile.plan as PlanType] ?? PLAN_LIMITS.free,
186	            stripe_subscription_id: subscription.id,
187	            billing_cycle_end: billingCycleEnd,
188	            updated_at: new Date().toISOString(),
189	          })
190	          .eq("id", profile.id);
191	
192	        if (error) {
193	          console.error("customer.subscription.updated profile update error:", error);
194	        } else {
195	          console.log(
196	            `Updated subscription for user ${profile.id}: ${profile.plan} → ${newPlan} (status: ${subscription.status})`
197	          );
198	        }
199	        break;
200	      }
201	
202	      // ── customer.subscription.deleted ────────────────────────────
203	      case "customer.subscription.deleted": {
204	        const subscription = event.data.object as Stripe.Subscription;
205	
206	        const { data: profile, error: profileError } = await supabase
207	          .from("profiles")
208	          .select("id")
209	          .eq("stripe_customer_id", subscription.customer as string)
210	          .single();
211	
212	        if (profileError || !profile) {
213	          console.error(
214	            "customer.subscription.deleted: profile not found for customer",
215	            subscription.customer
216	          );
217	          break;
218	        }
219	
220	        const { error } = await supabase
221	          .from("profiles")
222	          .update({
223	            plan: "free",
224	            scan_limit: PLAN_LIMITS.free,
225	            stripe_subscription_id: null,
226	            billing_cycle_end: null,
227	            updated_at: new Date().toISOString(),
228	          })
229	          .eq("id", profile.id);
230	
231	        if (error) {
232	          console.error("customer.subscription.deleted profile update error:", error);
233	        } else {
234	          console.log(`Downgraded user ${profile.id} to free plan (subscription deleted)`);
235	        }
236	        break;
237	      }
238	
239	      // ── invoice.payment_failed ────────────────────────────────────
240	      case "invoice.payment_failed": {
241	        const invoice = event.data.object as Stripe.Invoice;
242	        console.log(
243	          `Payment failed for customer ${invoice.customer} — invoice ${invoice.id} — amount ${invoice.amount_due} ${invoice.currency}`
244	        );
245	        // Future: trigger a dunning email via send-email function
246	        break;
247	      }
248	
249	      default:
250	        // Unhandled event type — acknowledge receipt to avoid retries
251	        console.log(`Unhandled webhook event type: ${event.type}`);
252	    }
253	
254	    return new Response(
255	      JSON.stringify({ received: true }),
256	      { status: 200, headers: { "Content-Type": "application/json" } }
257	    );
258	  } catch (error: unknown) {
259	    const message = error instanceof Error ? error.message : "Handler error";
260	    console.error(`Error handling ${event.type}:`, error);
261	    return new Response(
262	      JSON.stringify({ error: message }),
263	      { status: 500, headers: { "Content-Type": "application/json" } }
264	    );
265	  }
266	});
